name: Release
run-name: Release ${{ github.ref_name }}

on: { push: { tags: ["[0-9]+.[0-9]+.[0-9]+"] }, workflow_dispatch: {} }

permissions: { contents: read }

jobs:
  validate: { uses: $/.github/workflows/ci.yml }

  release:
    needs: validate
    runs-on: ubuntu-latest
    if: github.repository == 'kjanat/dprint-plugin-shuck'
    permissions: { contents: write }
    env: { ref: "${{ github.ref_name }}", download_dir: artifact }
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7
        with: { fetch-depth: 0 }
      - parallel:
          - uses: actions/download-artifact@9000827ccba6bdab643e8b6fd33ac0654aef8333 # v8.0.2
            with: { name: plugin, path: "${{ env.download_dir }}" }
          - uses: jdx/mise-action@6612f0ef07ed2a736cd1e00a94a065522dd41195 # v5.2.5
      - run: run verify-release "${ref}"
      - run: run release-notes
      - name: "Publish release ${{ env.ref }}"
        env: { GH_TOKEN: "${{ github.token }}" }
        working-directory: ${{ env.download_dir }}
        run: gh release create "${ref}" --verify-tag
          --title "$(cat release-title.txt)"
          --generate-notes --notes-file release-notes.md
          plugin.wasm schema.json

